protocol Letter { func draw() -> String; func cloned() -> any Letter }

struct Envelope {                        // value-semantic facade
    private var letter: any Letter
    init(_ letter: any Letter) { self.letter = letter }
    func draw() -> String { letter.draw() }             // forwarding
    func using(_ new: any Letter) -> Envelope { Envelope(new) }   // swap
}
